#!/usr/bin/env perl
use strict;
use warnings;
use feature 'say';
use feature 'signatures';
sub greet ($name) {
    return "Hello, $name!";
}

sub add ($x, $y = 0) {
    return $x + $y;
}

sub average {
    my @nums = @_;
    return undef unless @nums;
    my $sum = 0;
    $sum += $_ for @nums;
    return $sum / @nums;
}

say greet("Ruby");
say add(3, 4);
say add(5);
printf "平均分: %.2f\n", average(80, 90, 100);

#!/usr/bin/env perl
use strict;
use warnings;
use feature 'say';
sub stats {
    my @items = @_;
    return unless @items;
    return $items[0] unless wantarray;
    my $sum = 0;
    $sum += $_ for @items;
    return ($sum, $sum / @items, scalar @items);
}
my ($total, $avg, $count) = stats(10, 20, 30);
say "合计 $total, 平均 $avg, 数量 $count";
sub format_name {
    my (%opt) = @_;
    return ($opt{last} // "") . " " . ($opt{first} // "");
}
say format_name(first => "San", last => "Zhang");
sub factorial {
    my ($n) = @_;
    return 1 if $n <= 1;
    return $n * factorial($n - 1);
}
say "5! = ", factorial(5);

