#!/usr/bin/env perl
use strict;
use warnings;
use feature 'say';

package Point;
sub new {
    my ($class, %args) = @_;
    my $self = { x => $args{x} // 0, y => $args{y} // 0 };
    return bless $self, $class;
}
sub x { my $self = shift; return $self->{x} }
sub move {
    my ($self, $dx, $dy) = @_;
    $self->{x} += $dx;
    $self->{y} += $dy;
    return $self;
}
sub to_string { my $self = shift; return sprintf("(%d, %d)", $self->{x}, $self->{y}) }

package main;
my $p = Point->new(x => 1, y => 2);
$p->move(3, 4);
say $p->to_string;

