sub area { die "子类必须实现 area 方法" }

package Circle;
use parent -norequire, 'Shape';
sub area { my $self = shift; return 3.14159 * $self->{r} ** 2 }

package Square;
use parent -norequire, 'Shape';
sub area { my $self = shift; return $self->{side} ** 2 }

package main;
for my $shape (Circle->new(r => 2), Square->new(side => 3)) {
    printf "%s 面积 %.2f\n", ref $shape, $shape->area;
}

