use warnings;
use feature 'say';

my @pids;
for my $i (1 .. 3) {
    my $pid = fork();
    die "fork 失败: $!" unless defined $pid;
    if ($pid == 0) {
        sleep 1;
        say "子进程 $i (pid $$) 完成";
        exit 0;
    }
    push @pids, $pid;
}
waitpid($_, 0) for @pids;
