#!/usr/bin/env perl
use strict;
use warnings;
use feature 'say';
use Getopt::Long;

my ($verbose, $count, $file);
GetOptions(
    'verbose|v' => \$verbose,
    'count|c=i' => \$count,
    'file|f=s'  => \$file,
) or die "用法: $0 [-v] [-c N] [-f 文件]\n";

$count //= 1;
say "详细模式开启" if $verbose;
say "指定文件: $file" if defined $file;

my $n = 0;
while (my $line = <>) {
    $n++;
    say "第 $n 行: $line" if $verbose;
    last if $n >= $count;
}
say "共处理 $n 行";
exit 0;

#!/usr/bin/env perl
