    next unless $line =~ /^(\d{4}-\d{2}-\d{2}) (\d{2}):\d{2}:\d{2} (ERROR|INFO|WARN)/;
    my ($date, $hour, $level) = ($1, $2, $3);
    $level_count{$level}++;
    $hour_count{$hour}++;
}

say "按级别统计:";
say "  $_: $level_count{$_}" for sort keys %level_count;
say "按小时统计:";
for my $hour (sort keys %hour_count) {
    say "  $hour 时: $hour_count{$hour} 条";
}
say "总计: ", scalar keys %level_count, " 种级别";

