#!/usr/bin/env perl
use strict;
use warnings;
use feature 'say';

# 1. 每个文件都启用 strict 与 warnings
# 2. 用 my 声明最小作用域变量，避免全局状态
# 3. 子程序保持短小，参数用签名或列表显式接收
# 4. 用 perltidy 格式化，用 perlcritic --severity 3 做静态检查
# 5. 公开子程序写 POD 文档，并用 perldoc 验证

sub parse_pair {
    my ($text) = @_;
    return unless defined $text;
    my ($key, $value) = split /=/, $text, 2;
    return ($key, $value);
}

my ($k, $v) = parse_pair("debug=1");
say "配置: $k => $v";
my @empty = parse_pair(undef);
say "无输入时返回元素个数: ", scalar @empty;

